import{_ as a,o as t,c as l,ak as i}from"./chunks/framework.DDz3O3n6.js";const c=JSON.parse('{"title":"Godot 4 vs Godot 3","description":"","frontmatter":{"title":"Godot 4 vs Godot 3","index":1},"headers":[],"relativePath":"godot/godot-4-vs-godot-3.md","filePath":"godot/godot-4-vs-godot-3.md","lastUpdated":1780628909000}'),d={name:"godot/godot-4-vs-godot-3.md"};function r(e,o,n,s,h,p){return t(),l("div",null,[...o[0]||(o[0]=[i('<h1 id="godot-4-vs-godot-3-到底该选谁" tabindex="-1">Godot 4 vs Godot 3：到底该选谁？ <a class="header-anchor" href="#godot-4-vs-godot-3-到底该选谁" aria-label="Permalink to “Godot 4 vs Godot 3：到底该选谁？”">​</a></h1><p>如果把 Godot 比作一辆车，那么 <strong>Godot 3</strong> 就像一台老练、稳定、很好上手的老车，<br> 而 <strong>Godot 4</strong> 更像一台更新、更强、但也多了些新零件的新车型。</p><p>它们都能开，都会把你送到“做出游戏”这个目的地。<br> 区别在于：你想坐一辆熟悉的车，还是直接上新款。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to “先说结论”">​</a></h2><p>如果你现在是新手，<strong>优先学 Godot 4</strong>。<br> 如果你在看老教程、旧项目、或者想维护旧工程，再去了解 Godot 3。</p><p>简单说：</p><ul><li><strong>新项目</strong>：选 Godot 4</li><li><strong>老项目</strong>：看 Godot 3</li><li><strong>学习教程</strong>：尽量跟着 Godot 4 走</li></ul><h2 id="godot-4-和-godot-3-最大的区别" tabindex="-1">Godot 4 和 Godot 3 最大的区别 <a class="header-anchor" href="#godot-4-和-godot-3-最大的区别" aria-label="Permalink to “Godot 4 和 Godot 3 最大的区别”">​</a></h2><h3 id="_1-引擎更新了" tabindex="-1">1. 引擎更新了 <a class="header-anchor" href="#_1-引擎更新了" aria-label="Permalink to “1. 引擎更新了”">​</a></h3><p>Godot 4 不是小修小补，而是一次比较大的升级。<br> 它带来了更现代的底层架构，也加了很多新功能。</p><p>这意味着：</p><ul><li>一些旧写法变了</li><li>一些 API 不一样了</li><li>老教程不能完全照抄</li></ul><p>所以你会看到很多 Godot 3 教程在 Godot 4 里“能看懂，但不能直接复制”。</p><h3 id="_2-渲染和画面能力更强" tabindex="-1">2. 渲染和画面能力更强 <a class="header-anchor" href="#_2-渲染和画面能力更强" aria-label="Permalink to “2. 渲染和画面能力更强”">​</a></h3><p>Godot 4 在图形表现上比 Godot 3 更现代。<br> 如果你想做更漂亮的光照、特效、3D 表现，Godot 4 更合适。</p><p>但别担心：<br> 如果你只是做 2D 小游戏，Godot 4 一样很好用，甚至更舒服。</p><h3 id="_3-gdscript-和节点系统更顺手了" tabindex="-1">3. GDScript 和节点系统更顺手了 <a class="header-anchor" href="#_3-gdscript-和节点系统更顺手了" aria-label="Permalink to “3. GDScript 和节点系统更顺手了”">​</a></h3><p>Godot 的核心还是那个熟悉的味道：</p><ul><li>场景</li><li>节点</li><li>信号</li><li>GDScript</li></ul><p>所以你不用担心“换了新版本就完全不会了”。<br> 实际上，Godot 4 和 Godot 3 的思路是非常接近的。</p><p>你学会一个，另一个也能很快看懂。</p><h3 id="_4-老教程会有坑" tabindex="-1">4. 老教程会有坑 <a class="header-anchor" href="#_4-老教程会有坑" aria-label="Permalink to “4. 老教程会有坑”">​</a></h3><p>这点很重要。</p><p>很多 Godot 3 教程里的代码，在 Godot 4 里可能会出现：</p><ul><li>函数名变了</li><li>节点名变了</li><li>输入系统变了</li><li>摄像机、碰撞、动画写法变了</li></ul><p>所以如果你是新手，最好直接从 Godot 4 教程开始，少踩很多坑。</p><h2 id="那-godot-3-还有必要学吗" tabindex="-1">那 Godot 3 还有必要学吗？ <a class="header-anchor" href="#那-godot-3-还有必要学吗" aria-label="Permalink to “那 Godot 3 还有必要学吗？”">​</a></h2><p>有，但看场景。</p><h3 id="适合学-godot-3-的情况" tabindex="-1">适合学 Godot 3 的情况 <a class="header-anchor" href="#适合学-godot-3-的情况" aria-label="Permalink to “适合学 Godot 3 的情况”">​</a></h3><ul><li>你正在维护旧项目</li><li>你跟着的教程是 Godot 3 版本</li><li>你想先快速理解 Godot 的基本思路</li></ul><h3 id="不太建议的情况" tabindex="-1">不太建议的情况 <a class="header-anchor" href="#不太建议的情况" aria-label="Permalink to “不太建议的情况”">​</a></h3><ul><li>你准备从零开始做新游戏</li><li>你想直接学最新写法</li><li>你不想被老教程坑到怀疑人生</li></ul><h2 id="对新手来说-最现实的建议" tabindex="-1">对新手来说，最现实的建议 <a class="header-anchor" href="#对新手来说-最现实的建议" aria-label="Permalink to “对新手来说，最现实的建议”">​</a></h2><p>如果你现在刚开始学：</p><ol><li>直接安装 Godot 4</li><li>看 Godot 4 教程</li><li>用 Godot 4 跟着做一个小项目</li><li>需要时再回头看 Godot 3 的旧资料</li></ol><p>这样学习路线最顺，也最不容易乱。</p><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to “一句话总结”">​</a></h2><p><strong>Godot 3 像“成熟老版本”，Godot 4 像“更现代的新版本”。</strong><br> 如果你是现在才开始学，基本不用纠结，直接学 Godot 4 就对了。</p><h2 id="下一步学什么" tabindex="-1">下一步学什么？ <a class="header-anchor" href="#下一步学什么" aria-label="Permalink to “下一步学什么？”">​</a></h2><p>建议你继续看：</p><ul><li>什么是 Godot Engine</li><li>为什么选择 Godot</li><li>如何安装 Godot 4</li><li>编辑器界面怎么用</li><li>第一个 Hello World 场景怎么做</li></ul><p>学到这里，你就已经真正迈出第一步了。</p>',42)])])}const g=a(d,[["render",r]]);export{c as __pageData,g as default};
